import{_ as s,I as t,o as r,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"تطوير منصة وكيل تخطيط السفر الذكي - مشروع عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"ar-sa/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"ar-sa/stage-2/assignments/travel-planning-agent-platform/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=e('<h1 id="تطوير-منصة-وكيل-تخطيط-السفر-الذكي-مشروع-عملي" tabindex="-1">تطوير منصة وكيل تخطيط السفر الذكي - مشروع عملي <a class="header-anchor" href="#تطوير-منصة-وكيل-تخطيط-السفر-الذكي-مشروع-عملي" aria-label="Permalink to “تطوير منصة وكيل تخطيط السفر الذكي - مشروع عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب منك هذا المشروع العملي العمل على أساس مستند متطلبات منتج (PRD) حقيقي، وبناء منصة وكيل تخطيط سفر ذكي من الصفر. ستبني منتج AI كاملاً قادراً على استقبال مدخلات منظمة وإنشاء خط سير يومي ودعم الحفظ وإعادة الاستخدام - وليس مجرد روبوت دردشة، بل منتج يمتلك قدرات إدارة المهام.</p><p>هذا هو مشروع Stage 2 التطبيقي الشامل. التحدي الأساسي لهذا المشروع يكمن في: كيف تجعل AI يُنشئ خطط سفر منظمة وقابلة للاستخدام، بدلاً من نص طويل غير قابل للتشغيل.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات الويب واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">المكتبة الحديثة للمكونات</a>)</li><li>تصميم وتطوير واجهات البرمجيات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع العملي، ستتمكن من:</p><ol><li>قراءة PRD واستخراج قائمة مهام تطوير منصة الوكيل الذكي</li><li>تصميم نماذج إدخال منظمة وتنسيقات إخراج منظمة</li><li>تنفيذ طبقة تنسيق الوكيل الذكي لمعالجة مدخلات المستخدم واستدعاء النموذج وتخزين النتائج</li><li>بناء حلقة أعمال &quot;توليد ← حفظ ← إعادة استخدام&quot;</li><li>إكمال الاختبار الشامل من طرف إلى طرف وتسليم نموذج أولي لمنتج AI قابل للعرض</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستبنيه هو منصة وكيل تخطيط سفر ذكي:</p><table tabindex="0"><thead><tr><th>الوظيفة</th><th>الوصف</th></tr></thead><tbody><tr><td><strong>تخطيط الرحلة</strong></td><td>يُدخل المستخدم نقطة الانطلاق والوجهة والتاريخ والميزانية والتفضيلات، ويُنشئ النظام خط سير يومي</td></tr><tr><td><strong>تفكيك الميزانية</strong></td><td>تتضمن نتائج الرحلة توزيع الميزانية والاقتراحات</td></tr><tr><td><strong>إدارة السجل</strong></td><td>يمكن للمستخدم حفظ الخطط السابقة وإعادة إنشائها وتصديرها</td></tr><tr><td><strong>لوحة الإدارة</strong></td><td>يعرض المسؤول الوجهات الشائعة والمهام الفاشلة وتعليقات المستخدمين</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">مدخل PRD</p><p>مستند متطلبات هذا المشروع متاح على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',14)),h("div",c,[i(n,null,{default:o(()=>[i(l,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD وتوضيح الصفحات وتنسيق الوكيل وهياكل الإدخال والإخراج"},{title:"بناء الهيكل",description:"استخدام AI لإنشاء هيكل الصفحة الرئيسية وصفحة التخطيط وصفحة السجل ولوحة الإدارة"},{title:"التطوير التكراري",description:"إضافة الإخراج المنظم وحالات المهام وإدارة السجل لكل وحدة"},{title:"الاختبار والنشر",description:"الاختبار الشامل من طرف إلى طرف والنشر والتحضير للعرض"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركز على الإجابة عن الأسئلة التالية:</p><ul><li>هل الإصدار الأول يقتصر على وجهة واحدة فقط؟</li><li>هل يجب أن يكون إخراج الرحلة منظماً؟ وما هو الهيكل؟</li><li>ما مدى عمق قدرات التصدير؟ (رابط مشاركة / PDF / صورة)</li><li>ما هو نطاق إحصائيات لوحة الإدارة وسجلات المهام؟</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ في كتابة الكود. سوء فهم المتطلبات هو السبب الأكثر شيوعاً لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;صفحة التخطيط&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;طبقة تنسيق الوكيل الذكي&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;استدعاء النموذج&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;قاعدة البيانات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;الخطط السابقة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;إحصائيات وسجلات لوحة الإدارة&quot;]</span></span></code></pre></div><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-إنشاء-الصفحات-الأمامية" tabindex="-1">2.1 إنشاء الصفحات الأمامية <a class="header-anchor" href="#_2-1-إنشاء-الصفحات-الأمامية" aria-label="Permalink to “2.1 إنشاء الصفحات الأمامية”">​</a></h3><p>مرجع لموجه الأوامر:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بناءً على PRD الحالي، ساعدني في إنشاء هيكل أمامي لمنصة وكيل تخطيط السفر الذكي.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. الصفحات تتضمن: الصفحة الرئيسية، صفحة التخطيط، صفحة تفاصيل الرحلة، صفحة السجلات، صفحة الإدارة</span></span>
<span class="line"><span>2. الجانب الأيسر من صفحة التخطيط هو نموذج والجانب الأيمن هو معاينة النتائج</span></span>
<span class="line"><span>3. إنشاء هيكل الصفحات والبيانات الوهمية فقط، دون ربط واجهات حقيقية</span></span>
<span class="line"><span>4. النمط يجب أن يشبه منتجات AI الحديثة</span></span></code></pre></div><h3 id="_2-2-التحقق-من-هيكل-الصفحات" tabindex="-1">2.2 التحقق من هيكل الصفحات <a class="header-anchor" href="#_2-2-التحقق-من-هيكل-الصفحات" aria-label="Permalink to “2.2 التحقق من هيكل الصفحات”">​</a></h3><p>تحقق من كل عنصر:</p><ul><li>[ ] هل حقول نموذج صفحة التخطيط تتوافق مع PRD</li><li>[ ] هل يمكن لمنطقة معاينة النتائج عرض بيانات الرحلة المنظمة</li><li>[ ] هل يمكن لصفحة السجلات عرض خطط متعددة</li><li>[ ] هل يمكن لصفحة لوحة الإدارة عرض البيانات الإحصائية</li></ul><h2 id="الجزء-الثالث-التطوير-التكراري" tabindex="-1">الجزء الثالث: التطوير التكراري <a class="header-anchor" href="#الجزء-الثالث-التطوير-التكراري" aria-label="Permalink to “الجزء الثالث: التطوير التكراري”">​</a></h2><h3 id="_3-1-التقدم-حسب-الوحدات" tabindex="-1">3.1 التقدم حسب الوحدات <a class="header-anchor" href="#_3-1-التقدم-حسب-الوحدات" aria-label="Permalink to “3.1 التقدم حسب الوحدات”">​</a></h3><ol><li><strong>المصادقة</strong>: التسجيل، تسجيل الدخول</li><li><strong>نموذج التخطيط</strong>: إدخال منظم (نقطة الانطلاق، الوجهة، التاريخ، الميزانية، التفضيلات)</li><li><strong>تنسيق الوكيل الذكي</strong>: استقبال الإدخال ← استدعاء النموذج ← تحليل الإخراج المنظم</li><li><strong>عرض النتائج</strong>: عرض الرحلة حسب اليوم، تفكيك الميزانية، الاقتراحات</li><li><strong>إدارة السجل</strong>: حفظ الخطة، إعادة الإنشاء، التصدير</li><li><strong>لوحة الإدارة</strong>: الوجهات الشائعة، المهام الفاشلة، تعليقات المستخدمين</li><li><strong>حالات المهام</strong>: إدارة الحالة (قيد الإنشاء / نجاح / فشل) وتسجيل الأخطاء</li></ol><h3 id="_3-2-الفحص-الذاتي-للوحدات" tabindex="-1">3.2 الفحص الذاتي للوحدات <a class="header-anchor" href="#_3-2-الفحص-الذاتي-للوحدات" aria-label="Permalink to “3.2 الفحص الذاتي للوحدات”">​</a></h3><table tabindex="0"><thead><tr><th>عنصر الفحص</th><th>طريقة التحقق</th></tr></thead><tbody><tr><td>اكتمال الإدخال</td><td>هل حقول النموذج تتوافق مع PRD</td></tr><tr><td>تنظيم الإخراج</td><td>هل نتائج الرحلة هي بيانات منظمة (وليس نصاً طويلاً)</td></tr><tr><td>توافق البيانات</td><td>هل بيانات trip و itinerary و logs متطابقة</td></tr><tr><td>التحقق من الحلقة</td><td>هل يمكن عرض &quot;إدخال ← توليد ← حفظ ← إعادة إنشاء&quot;</td></tr></tbody></table><h2 id="الجزء-الرابع-الاختبار-والنشر" tabindex="-1">الجزء الرابع: الاختبار والنشر <a class="header-anchor" href="#الجزء-الرابع-الاختبار-والنشر" aria-label="Permalink to “الجزء الرابع: الاختبار والنشر”">​</a></h2><h3 id="_4-1-اختبار-من-طرف-إلى-طرف" tabindex="-1">4.1 اختبار من طرف إلى طرف <a class="header-anchor" href="#_4-1-اختبار-من-طرف-إلى-طرف" aria-label="Permalink to “4.1 اختبار من طرف إلى طرف”">​</a></h3><p>تحقق من السيناريوهات التالية على الأقل:</p><ul><li>إدخال معلمات الرحلة ← توليد خط سير يومي ← عرض تفكيك الميزانية ← حفظ في السجل</li><li>إعادة إنشاء رحلة من السجلات</li><li>عرض المسؤول لإحصائيات المهام وسجلات الفشل</li></ul><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (يتضمن README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الرئيسية (صفحة التخطيط، صفحة تفاصيل الرحلة، صفحة السجلات، لوحة الإدارة)</li><li>[ ] فيديو عرض مدته 60 ثانية</li></ul><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البُعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>توافق PRD</td><td>الصفحات والوظائف وهياكل البيانات تتوافق بشكل أساسي مع PRD</td><td>القدرة على شرح قرارات التصميم بوضوح</td></tr><tr><td>حلقة المنتج</td><td>تخطيط ← حفظ ← سجل ← إعادة إنشاء يعمل بشكل كامل</td><td>دعم التصدير والمشاركة</td></tr><tr><td>جودة الإخراج</td><td>نتائج الرحلة منظمة وقابلة للقراءة</td><td>تفكيك الميزانية معقول والاقتراحات مستهدفة</td></tr><tr><td>قدرات لوحة الإدارة</td><td>يمكن عرض إحصائيات المهام وسجلات الفشل</td><td>توجد تحليلات للوجهات الشائعة</td></tr><tr><td>اكتمال الهندسة</td><td>تم ربط سلسلة الواجهة الأمامية والخلفية وقاعدة البيانات واستدعاء النموذج</td><td>إدارة حالات المهام مكتملة والأخطاء قابلة للتتبع</td></tr></tbody></table><h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام المكتبة الحديثة للمكونات</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات بمساعدة النماذج اللغوية الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li></ul>`,30))])}const x=s(p,[["render",b]]);export{P as __pageData,x as default};
